/// Glass material tokens, resolved per brightness.
@immutable
class FvGlass extends ThemeExtension<FvGlass> {
  const FvGlass({
    required this.fillHigh,
    required this.fillLow,
    required this.edge,
    required this.edgeDim,
    required this.specular,
    required this.cast,
    required this.agent,
    required this.emergency,
    required this.success,
    required this.warning,
    required this.faint,
  });

  final Color fillHigh;
  final Color fillLow;
  final Color edge;
  final Color edgeDim;
  final Color specular;
  final Color cast;
  final Color agent;
  final Color emergency;
  final Color success;
  final Color warning;
  final Color faint;

  static const double blurThin = 9;
  static const double blurRegular = 18;
  static const double blurThick = 30;
  static const int blurBudget = 3;

  static const light = FvGlass(
    fillHigh: Color(0xC7FFFFFF),
    fillLow: Color(0x8FFFFFFF),
    edge: Color(0xD9FFFFFF),
    edgeDim: Color(0x1A146CFF),
    specular: Color(0xFFFFFFFF),
    cast: Color(0x1A0B2545),
    agent: AppColors.agent,
    emergency: AppColors.emergency,
    success: AppColors.success,
    warning: AppColors.warning,
    faint: AppColors.faint,
  );

  static const dark = FvGlass(
    fillHigh: Color(0x8C1E345C),
    fillLow: Color(0x610C182E),
    edge: Color(0x38A0C8FF),
    edgeDim: Color(0x73000000),
    specular: Color(0x38BED7FF),
    cast: Color(0x8C000000),
    agent: AppColors.agentDark,
    emergency: AppColors.emergencyDark,
    success: AppColors.successDark,
    warning: AppColors.warningDark,
    faint: AppColors.faintDark,
  );

  @override
  FvGlass copyWith({
    Color? fillHigh,
    Color? fillLow,
    Color? edge,
    Color? edgeDim,
    Color? specular,
    Color? cast,
    Color? agent,
    Color? emergency,
    Color? success,
    Color? warning,
    Color? faint,
  }) {
    return FvGlass(
      fillHigh: fillHigh ?? this.fillHigh,
      fillLow: fillLow ?? this.fillLow,
      edge: edge ?? this.edge,
      edgeDim: edgeDim ?? this.edgeDim,
      specular: specular ?? this.specular,
      cast: cast ?? this.cast,
      agent: agent ?? this.agent,
      emergency: emergency ?? this.emergency,
      success: success ?? this.success,
      warning: warning ?? this.warning,
      faint: faint ?? this.faint,
    );
  }

  @override
  FvGlass lerp(ThemeExtension<FvGlass>? other, double t) {
    if (other is! FvGlass) return this;
    return FvGlass(
      fillHigh: Color.lerp(fillHigh, other.fillHigh, t)!,
      fillLow: Color.lerp(fillLow, other.fillLow, t)!,
      edge: Color.lerp(edge, other.edge, t)!,
      edgeDim: Color.lerp(edgeDim, other.edgeDim, t)!,
      specular: Color.lerp(specular, other.specular, t)!,
      cast: Color.lerp(cast, other.cast, t)!,
      agent: Color.lerp(agent, other.agent, t)!,
      emergency: Color.lerp(emergency, other.emergency, t)!,
      success: Color.lerp(success, other.success, t)!,
      warning: Color.lerp(warning, other.warning, t)!,
      faint: Color.lerp(faint, other.faint, t)!,
    );
  }
}

/// Convenience accessor: `context.glass.edge`.
extension FvGlassContext on BuildContext {
  FvGlass get glass =>
      Theme.of(this).extension<FvGlass>() ?? FvGlass.light;
}

ThemeData buildAppTheme({Brightness brightness = Brightness.light}) {
  final isDark = brightness == Brightness.dark;

  final primary = isDark ? AppColors.primaryDark : AppColors.primary;
  final surface = isDark ? AppColors.surfaceDark : AppColors.surface;
  final background = isDark ? AppColors.backgroundDark : AppColors.background;
  final text = isDark ? AppColors.textDark : AppColors.text;
  final textHeading = isDark ? AppColors.textHeadingDark : AppColors.textHeading;
  final muted = isDark ? AppColors.mutedDark : AppColors.muted;
  final border = isDark ? AppColors.borderDark : AppColors.border;
  final danger = isDark ? AppColors.dangerDark : AppColors.danger;
  final onPrimary = Colors.white;

  final scheme = ColorScheme.fromSeed(
    seedColor: primary,
    brightness: brightness,
    primary: primary,
    onPrimary: onPrimary,
    surface: surface,
    error: danger,
  );

  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    brightness: brightness,
    scaffoldBackgroundColor: background,
    extensions: <ThemeExtension<dynamic>>[
      isDark ? FvGlass.dark : FvGlass.light,
    ],
    textTheme: TextTheme(
      displaySmall: TextStyle(
        fontWeight: FontWeight.w800,
        letterSpacing: -0.5,
        height: 1.08,
        color: textHeading,
      ),
      headlineSmall: TextStyle(
        fontWeight: FontWeight.w700,
        letterSpacing: -0.3,
        color: textHeading,
      ),
      titleLarge: TextStyle(fontWeight: FontWeight.w700, color: textHeading),
      titleMedium: TextStyle(fontWeight: FontWeight.w600, color: text),
      bodyLarge: TextStyle(fontSize: 16, height: 1.55, color: text),
      bodyMedium: TextStyle(fontSize: 15, height: 1.55, color: text),
      bodySmall: TextStyle(fontSize: 13, height: 1.45, color: muted),
      labelLarge: TextStyle(fontWeight: FontWeight.w600, color: text),
    ),
    appBarTheme: AppBarTheme(
      backgroundColor: Colors.transparent,
      surfaceTintColor: Colors.transparent,
      foregroundColor: text,
      elevation: 0,
      scrolledUnderElevation: 0,
      centerTitle: false,
      titleTextStyle: TextStyle(
        fontSize: 18,
        fontWeight: FontWeight.w600,
        letterSpacing: -0.2,
        color: text,
      ),
    ),
    cardTheme: CardThemeData(
      color: surface.withValues(alpha: isDark ? 0.65 : 0.85),
      surfaceTintColor: Colors.transparent,
      elevation: 0,
      margin: const EdgeInsets.only(bottom: 10),
      shape: RoundedRectangleBorder(
        side: BorderSide(color: border),
        borderRadius: const BorderRadius.all(Radius.circular(20)),
      ),
    ),
    listTileTheme: ListTileThemeData(
      iconColor: primary,
      textColor: text,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(20)),
      ),
    ),
    dividerTheme: DividerThemeData(color: border, thickness: 1, space: 1),
    chipTheme: ChipThemeData(
      backgroundColor: surface.withValues(alpha: isDark ? 0.4 : 0.6),
      side: BorderSide(color: border),
      labelStyle: TextStyle(fontWeight: FontWeight.w500, color: text),
      shape: const StadiumBorder(),
    ),
    inputDecorationTheme: InputDecorationTheme(
      filled: true,
      fillColor: surface.withValues(alpha: isDark ? 0.45 : 0.66),
      hintStyle: TextStyle(color: muted),
      labelStyle: TextStyle(color: muted),
      border: OutlineInputBorder(
        borderRadius: const BorderRadius.all(Radius.circular(14)),
        borderSide: BorderSide(color: border),
      ),
      enabledBorder: OutlineInputBorder(
        borderRadius: const BorderRadius.all(Radius.circular(14)),
        borderSide: BorderSide(color: border),
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: const BorderRadius.all(Radius.circular(14)),
        borderSide: BorderSide(color: primary, width: 2),
      ),
    ),
    elevatedButtonTheme: ElevatedButtonThemeData(
      style: ElevatedButton.styleFrom(
        minimumSize: const Size(44, 50),
        backgroundColor: primary,
        foregroundColor: onPrimary,
        elevation: 0,
        textStyle: const TextStyle(fontSize: 15, fontWeight: FontWeight.w600),
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(14)),
        ),
      ),
    ),
    outlinedButtonTheme: OutlinedButtonThemeData(
      style: OutlinedButton.styleFrom(
        minimumSize: const Size(44, 50),
        foregroundColor: text,
        side: BorderSide(color: border),
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.all(Radius.circular(14)),
        ),
      ),
    ),
    textButtonTheme: TextButtonThemeData(
      style: TextButton.styleFrom(foregroundColor: primary),
    ),
    snackBarTheme: SnackBarThemeData(
      behavior: SnackBarBehavior.floating,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(14)),
      ),
      backgroundColor: isDark ? AppColors.surfaceDark : AppColors.text,
    ),
  );
}
